    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('vat' in totals);
  assert.ok('voucher' in totals);
  assert.ok('total' in totals);
  assert.equal(Object.keys(totals).length, 5);
});

test('invoiceTotals with bulk discount (10+ units)', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 95000, lineDiscount = 0, amountAfter = 95000
  // bulkDiscount = roundCents(95000 * 2.5 / 100) = 2375
  // totalDiscount = 2375, base = 92625, vat = roundCents(92625 * 21 / 100) = 19451.25 → 19451
  // total = 92625 + 19451 = 112076
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals without bulk discount (9 units)', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 85500, lineDiscount = 0, no bulk discount
  // total = 85500 + roundCents(85500 * 21 / 100) = 85500 + 17955 = 103455
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 95000, lineDiscount = 9500, amountAfter = 85500
  // bulkDiscount = roundCents(85500 * 2.5 / 100) = roundCents(2137.5) = 2138
  // totalDiscount = 9500 + 2138 = 11638, base = 83362, vat = roundCents(83362 * 21 / 100) = 17506.02 → 17506
  // total = 83362 + 17506 = 100868
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

test('invoiceTotals bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 6000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 95000, lineDiscount = 0, bulkDiscount = 2375, base = 92625, vat = 19451
  // Line 2: lineTotal = 30000, lineDiscount = 0, bulkDiscount = 0, base = 30000, vat = 6300
  // subtotal = 125000, discount = 2375, vat = 25751, total = 148376
  assert.equal(totals.subtotal, 125000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 25751);
  assert.equal(totals.total, 148376);
});

test('invoiceTotals bulk discount with both line and bulk discounts', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 5000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 100000, lineDiscount = 5000, amountAfter = 95000
  // bulkDiscount = roundCents(95000 * 2.5 / 100) = 2375
  // totalDiscount = 5000 + 2375 = 7375, base = 92625, vat = roundCents(92625 * 21 / 100) = 19451
  // total = 92625 + 19451 = 112076
  assert.equal(totals.discount, 7375);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals bulk discount with exactly 10 units qualifies', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 10000, lineDiscount = 0, bulkDiscount = 250
  // base = 9750, vat = roundCents(9750 * 21 / 100) = 2047.5 → 2048
  // total = 9750 + 2048 = 11798
  assert.equal(totals.discount, 250);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals no bulk discount with 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 9000, no bulk discount
  // base = 9000, vat = roundCents(9000 * 21 / 100) = 1890
  // total = 9000 + 1890 = 10890
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 1000000, lineDiscount = 0, bulkDiscount = 25000
  // base = 975000, vat = roundCents(975000 * 21 / 100) = 204750
  // total = 975000 + 204750 = 1179750
  assert.equal(totals.discount, 25000);
  assert.equal(totals.total, 1179750);
});

test('invoiceTotals bulk discount with different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 10, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 95000, bulkDiscount = 2375, base = 92625, vat = 19451
  // Line 2: lineTotal = 370, bulkDiscount = roundCents(370 * 2.5 / 100) = 9, base = 361, vat = roundCents(361 * 9 / 100) = 32.49 → 32
  // subtotal = 95370, discount = 2384, vat = 19483, total = 114252
  assert.equal(totals.subtotal, 95370);
  assert.equal(totals.discount, 2384);
  assert.equal(totals.vat, 19483);
  assert.equal(totals.total, 114252);
});

test('invoiceTotals bulk discount preserves original discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 9, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 95000, lineDiscount = 9500, bulkDiscount = 2138, total discount = 11638
  // Line 2: lineTotal = 85500, lineDiscount = 8550, bulkDiscount = 0, total discount = 8550
  // total discount = 20188
  assert.equal(totals.discount, 20188);
});

