import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid input', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.customerName, 'Northwind Studio');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice fills in product details from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].name, 'Printed flyer A4 (each)');
  assert.equal(result.value.lines[0].unitPrice, 37);
  assert.equal(result.value.lines[0].vatRate, 9);
});

test('createInvoice rejects unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects non-existent dates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects undefined lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects fractional quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const linesCopy = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), linesCopy);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 5 * 9500 + 3 * 8500);
  assert.equal(totals.subtotal, 73000);
});

test('invoiceTotals with gold tier customer applies discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(result.value);
  // 5*9500 + 1*120000 = 47500 + 120000 = 167500
  // 5% gold discount = 8375
  // Amount after discount = 159125
  // VAT: 21% = 33416 (rounded)
  // total = 167500 - 8375 + 33416 = 192541
  assert.equal(totals.subtotal, 167500);
  assert.equal(totals.discount, 8375);
  assert.equal(totals.vat, 33416);
  assert.equal(totals.total, 192541);
});

test('invoiceTotals with empty lines', () => {
  const totals = invoiceTotals({ lines: [] });
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with single line', () => {
  const totals = invoiceTotals({
    lines: [{ qty: 10, unitPrice: 5000, vatRate: 21, discountPercent: 0 }],
  });
  // 10*5000 = 50000, VAT 21% = 10500, Total = 60500
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.vat, 10500);
  assert.equal(totals.total, 60500);
});

test('addLine adds a new line to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const added = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines.length, 2);
  assert.equal(added.value.lines[1].sku, 'DES-HOUR');
  assert.equal(added.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already on invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const added = addLine(result.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines.length, 1);
  assert.equal(added.value.lines[0].qty, 8);
});

test('addLine fills in product details from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const added = addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines[1].name, 'Logo package');
  assert.equal(added.value.lines[1].unitPrice, 120000);
  assert.equal(added.value.lines[1].vatRate, 21);
});

test('addLine rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const added = addLine(result.value, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(added, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects invalid quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const added = addLine(result.value, { sku: 'DES-HOUR', qty: 0 });
  assert.deepEqual(added, { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects fractional quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const added = addLine(result.value, { sku: 'DES-HOUR', qty: 1.5 });
  assert.deepEqual(added, { ok: false, error: 'QTY_INVALID' });
});

test('addLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21 }],
  };
  const added = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(added, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const original = JSON.stringify(result.value);
  addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
