test('invoiceTotals includes discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const totals = invoiceTotals(result.value);
  // 100 * 9500 = 950000
  // 10% discount = 95000
  // Amount after discount = 855000
  // 21% VAT = 179550
  // total = 950000 - 95000 + 179550 = 1034550
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 95000);
  assert.equal(totals.vat, 179550);
  assert.equal(totals.total, 1034550);
});

