import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 10, unitPrice: 9500 };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with single unit', () => {
  const line = { qty: 1, unitPrice: 1000 };
  assert.equal(lineTotal(line), 1000);
});

test('lineTotal with zero quantity', () => {
  const line = { qty: 0, unitPrice: 9500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large amounts', () => {
  const line = { qty: 1000, unitPrice: 500000 };
  assert.equal(lineTotal(line), 500000000);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 6000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 125000); // 95000 + 30000
});

test('invoiceTotals calculates discount correctly', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 4750); // 47500 * 10 / 100
});

test('invoiceTotals calculates VAT on discounted amount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 47500, discount = 2375, base = 45125, vat = 9476.25 → 9476
  assert.equal(totals.vat, 9476);
});

test('invoiceTotals with 0% VAT has no VAT', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 0);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 47500, no bulk discount, base = 47500, vat = roundCents(47500 * 21 / 100) = 9975
  // Line 2: lineTotal = 3700, bulk discount = 92.5 (rounded to 93), base = 3607, vat = roundCents(3607 * 9 / 100) = 324.63 → 325
  // Total vat = 10300
  assert.equal(totals.vat, 10300);
});

test('invoiceTotals with multiple lines and discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 6000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 95000, discount = 4750, base = 90250, vat = 18952
  // Line 2: lineTotal = 30000, discount = 3000, base = 27000, vat = 5670
  // subtotal = 125000, discount = 7750, vat = 24622, total = 141872
  assert.equal(totals.subtotal, 125000);
  assert.equal(totals.discount, 7750);
  assert.equal(totals.vat, 24622);
  assert.equal(totals.total, 141872);
});

test('invoiceTotals clamps negative total to 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 },
    ],
    voucher: { code: 'TEST', amount: 100000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  // base total without voucher = 109202, minus voucher = 99202
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 99202);
});

test('invoiceTotals without voucher has voucher = 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 210);
  assert.equal(totals.total, 1210);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = {
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with large amounts', () => {
  const invoice = {
    lines: [
      { qty: 1000, unitPrice: 500000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 500000000);
  assert.equal(totals.total, 605000000);
});

test('invoiceTotals returns correct structure', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('vat' in totals);
  assert.ok('voucher' in totals);
  assert.ok('total' in totals);
  assert.equal(Object.keys(totals).length, 5);
});

test('invoiceTotals with bulk discount (10+ units)', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 95000, lineDiscount = 0, amountAfter = 95000
  // bulkDiscount = roundCents(95000 * 2.5 / 100) = 2375
  // totalDiscount = 2375, base = 92625, vat = roundCents(92625 * 21 / 100) = 19451.25 → 19451
  // total = 92625 + 19451 = 112076
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals without bulk discount (9 units)', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 85500, lineDiscount = 0, no bulk discount
  // total = 85500 + roundCents(85500 * 21 / 100) = 85500 + 17955 = 103455
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 95000, lineDiscount = 9500, amountAfter = 85500
  // bulkDiscount = roundCents(85500 * 2.5 / 100) = roundCents(2137.5) = 2138
  // totalDiscount = 9500 + 2138 = 11638, base = 83362, vat = roundCents(83362 * 21 / 100) = 17506.02 → 17506
  // total = 83362 + 17506 = 100868
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

test('invoiceTotals bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 6000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: lineTotal = 95000, lineDiscount = 0, bulkDiscount = 2375, base = 92625, vat = 19451
  // Line 2: lineTotal = 30000, lineDiscount = 0, bulkDiscount = 0, base = 30000, vat = 6300
  // subtotal = 125000, discount = 2375, vat = 25751, total = 148376
  assert.equal(totals.subtotal, 125000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 25751);
  assert.equal(totals.total, 148376);
});

test('invoiceTotals bulk discount with both line and bulk discounts', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 5000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 100000, lineDiscount = 5000, amountAfter = 95000
  // bulkDiscount = roundCents(95000 * 2.5 / 100) = 2375
  // totalDiscount = 5000 + 2375 = 7375, base = 92625, vat = roundCents(92625 * 21 / 100) = 19451
  // total = 92625 + 19451 = 112076
  assert.equal(totals.discount, 7375);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals bulk discount with exactly 10 units qualifies', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 10000, lineDiscount = 0, bulkDiscount = 250
  // base = 9750, vat = roundCents(9750 * 21 / 100) = 2047.5 → 2048
  // total = 9750 + 2048 = 11798
  assert.equal(totals.discount, 250);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals no bulk discount with 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 9000, no bulk discount
  // base = 9000, vat = roundCents(9000 * 21 / 100) = 1890
  // total = 9000 + 1890 = 10890
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 10890);
});

